//! Blinded responder dispatch: a responder registers a filter under a random id, and events
//! matching that filter are queued in a per-subscription inbox the responder polls.
//!
//! This is the narrowest honest slice of `spec/03-anonymous-event-rfc.md`'s "Reaching a
//! responder" question: a responder can receive events it cares about without the node learning
//! who it is. The subscription id is generated by the responder (a random token), so the node
//! only ever knows that *some* subscription exists, never which `PeerIdentity` stands behind it.
//! The reporter side stays anonymous exactly as before -- the event payload is identity-stripped
//! (`anonymous_event.rs`).
//!
//! **What this explicitly is not.** Not a push notification: nothing leaves the node until the
//! responder polls its inbox. The node does learn the responder's network address (they poll),
//! just not their identity. Not durable: both the subscription registry and the inbox are
//! in-memory, so a restart loses them; a responder re-registers and re-searches the log. Not a
//! guarantee that a responder is reachable at all -- only that, if it polls, it will see what it
//! asked for. See `spec/14-responder-dispatch.md`.

use std::collections::HashMap;

use crate::anonymous_event::{AnonymousEvent, EventFilter};

/// A responder's filter, registered under a responder-chosen random id.
#[derive(Debug, Default)]
pub struct ResponderSubscriptionRegistry {
    subscriptions: HashMap<String, EventFilter>,
}

impl ResponderSubscriptionRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    /// Registers or replaces the filter for `subscription_id`. The id is generated by the
    /// responder (a random token), so the node never learns who they are. Returns the previous
    /// filter if there was one.
    pub fn upsert(&mut self, subscription_id: String, filter: EventFilter) -> Option<EventFilter> {
        self.subscriptions.insert(subscription_id, filter)
    }

    /// Removes a subscription, returning whether it existed.
    pub fn remove(&mut self, subscription_id: &str) -> bool {
        self.subscriptions.remove(subscription_id).is_some()
    }

    pub fn subscriptions(&self) -> &HashMap<String, EventFilter> {
        &self.subscriptions
    }
}

/// Per-subscription inboxes, filled when an event matching a subscription arrives.
#[derive(Debug, Default)]
pub struct ResponderInbox {
    inbox: HashMap<String, Vec<AnonymousEvent>>,
}

impl ResponderInbox {
    pub fn new() -> Self {
        Self::default()
    }

    /// Appends `event` to every subscription whose filter matches it.
    pub fn push_matching(&mut self, event: &AnonymousEvent, subscriptions: &HashMap<String, EventFilter>) {
        for (id, filter) in subscriptions {
            if filter.matches(event) {
                self.inbox.entry(id.clone()).or_default().push(event.clone());
            }
        }
    }

    /// Takes every event queued for `subscription_id`, clearing the inbox.
    pub fn drain(&mut self, subscription_id: &str) -> Vec<AnonymousEvent> {
        self.inbox.remove(subscription_id).unwrap_or_default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::anonymous_event::{CoarseLocation, EventKind, Severity};

    fn event(kind: EventKind) -> AnonymousEvent {
        AnonymousEvent {
            event_id: "evt-1".to_string(),
            kind,
            severity: Severity::High,
            observed_at: 1_700_000_400,
            location: CoarseLocation("9q8yy".to_string()),
            corroboration_nonce: "nonce-1".to_string(),
        }
    }

    #[test]
    fn a_matching_event_is_queued_for_a_subscription() {
        let mut registry = ResponderSubscriptionRegistry::new();
        registry.upsert(
            "sub-1".to_string(),
            EventFilter { kind: Some(crate::anonymous_event::EventKindCategory::MedicalEmergency), ..Default::default() },
        );
        let mut inbox = ResponderInbox::new();

        inbox.push_matching(
            &event(EventKind::MedicalEmergency(crate::anonymous_event::MedicalEmergencyKind::HeartIssue)),
            registry.subscriptions(),
        );
        inbox.push_matching(&event(EventKind::HazardObserved), registry.subscriptions());

        assert_eq!(inbox.drain("sub-1").len(), 1);
        assert!(inbox.drain("sub-1").is_empty());
    }

    #[test]
    fn a_non_matching_event_is_not_queued() {
        let mut registry = ResponderSubscriptionRegistry::new();
        registry.upsert(
            "sub-1".to_string(),
            EventFilter { kind: Some(crate::anonymous_event::EventKindCategory::MedicalEmergency), ..Default::default() },
        );
        let mut inbox = ResponderInbox::new();

        inbox.push_matching(&event(EventKind::HazardObserved), registry.subscriptions());
        assert!(inbox.drain("sub-1").is_empty());
    }

    #[test]
    fn a_subscription_is_blinded_and_replaceable() {
        let mut registry = ResponderSubscriptionRegistry::new();
        let first = EventFilter { location_prefix: Some("9q8".to_string()), ..Default::default() };
        let second = EventFilter { location_prefix: Some("abc".to_string()), ..Default::default() };
        assert!(registry.upsert("sub-1".to_string(), first).is_none());
        assert!(registry.upsert("sub-1".to_string(), second).is_some());
        assert_eq!(registry.subscriptions().len(), 1);
        assert!(registry.remove("sub-1"));
        assert!(!registry.remove("sub-1"));
    }
}
